module axi_lite_regs (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [31:0] s_axi_awaddr,
    input  wire        s_axi_awvalid,
    output wire        s_axi_awready,
    input  wire [31:0] s_axi_wdata,
    input  wire [3:0]  s_axi_wstrb,
    input  wire        s_axi_wvalid,
    output wire        s_axi_wready,
    output reg  [1:0]  s_axi_bresp,
    output reg         s_axi_bvalid,
    input  wire        s_axi_bready,
    input  wire [31:0] s_axi_araddr,
    input  wire        s_axi_arvalid,
    output wire        s_axi_arready,
    output reg  [31:0] s_axi_rdata,
    output reg  [1:0]  s_axi_rresp,
    output reg         s_axi_rvalid,
    input  wire        s_axi_rready
);

    reg [31:0] reg0;
    reg [31:0] reg1;
    reg [31:0] reg2;
    reg [31:0] reg3;

    reg        aw_saved;
    reg [31:0] awaddr_saved;

    reg        w_saved;
    reg [31:0] wdata_saved;
    reg [3:0]  wstrb_saved;

    /*
     * This flag is updated synchronously so changes to rst_n between clock
     * edges do not asynchronously affect the READY outputs.
     */
    reg active;

    assign s_axi_awready = active && !s_axi_bvalid && !aw_saved;
    assign s_axi_wready  = active && !s_axi_bvalid && !w_saved;
    assign s_axi_arready = active && !s_axi_rvalid;

    always @(posedge clk) begin
        if (!rst_n) begin
            reg0          <= 32'b0;
            reg1          <= 32'b0;
            reg2          <= 32'b0;
            reg3          <= 32'b0;

            aw_saved      <= 1'b0;
            awaddr_saved  <= 32'b0;
            w_saved       <= 1'b0;
            wdata_saved   <= 32'b0;
            wstrb_saved   <= 4'b0;

            s_axi_bresp   <= 2'b00;
            s_axi_bvalid  <= 1'b0;

            s_axi_rdata   <= 32'b0;
            s_axi_rresp   <= 2'b00;
            s_axi_rvalid  <= 1'b0;

            active        <= 1'b0;
        end else begin
            active <= 1'b1;

            if (s_axi_bvalid && s_axi_bready)
                s_axi_bvalid <= 1'b0;

            if (s_axi_awvalid && s_axi_awready) begin
                awaddr_saved <= s_axi_awaddr;
                aw_saved     <= 1'b1;
            end

            if (s_axi_wvalid && s_axi_wready) begin
                wdata_saved <= s_axi_wdata;
                wstrb_saved <= s_axi_wstrb;
                w_saved     <= 1'b1;
            end

            if (aw_saved && w_saved && !s_axi_bvalid) begin
                aw_saved     <= 1'b0;
                w_saved      <= 1'b0;
                s_axi_bvalid <= 1'b1;

                case (awaddr_saved)
                    32'h00000000: begin
                        if (wstrb_saved[0])
                            reg0[7:0]   <= wdata_saved[7:0];
                        if (wstrb_saved[1])
                            reg0[15:8]  <= wdata_saved[15:8];
                        if (wstrb_saved[2])
                            reg0[23:16] <= wdata_saved[23:16];
                        if (wstrb_saved[3])
                            reg0[31:24] <= wdata_saved[31:24];
                        s_axi_bresp <= 2'b00;
                    end

                    32'h00000004: begin
                        if (wstrb_saved[0])
                            reg1[7:0]   <= wdata_saved[7:0];
                        if (wstrb_saved[1])
                            reg1[15:8]  <= wdata_saved[15:8];
                        if (wstrb_saved[2])
                            reg1[23:16] <= wdata_saved[23:16];
                        if (wstrb_saved[3])
                            reg1[31:24] <= wdata_saved[31:24];
                        s_axi_bresp <= 2'b00;
                    end

                    32'h00000008: begin
                        if (wstrb_saved[0])
                            reg2[7:0]   <= wdata_saved[7:0];
                        if (wstrb_saved[1])
                            reg2[15:8]  <= wdata_saved[15:8];
                        if (wstrb_saved[2])
                            reg2[23:16] <= wdata_saved[23:16];
                        if (wstrb_saved[3])
                            reg2[31:24] <= wdata_saved[31:24];
                        s_axi_bresp <= 2'b00;
                    end

                    32'h0000000c: begin
                        if (wstrb_saved[0])
                            reg3[7:0]   <= wdata_saved[7:0];
                        if (wstrb_saved[1])
                            reg3[15:8]  <= wdata_saved[15:8];
                        if (wstrb_saved[2])
                            reg3[23:16] <= wdata_saved[23:16];
                        if (wstrb_saved[3])
                            reg3[31:24] <= wdata_saved[31:24];
                        s_axi_bresp <= 2'b00;
                    end

                    default: begin
                        s_axi_bresp <= 2'b10;
                    end
                endcase
            end

            if (s_axi_rvalid && s_axi_rready)
                s_axi_rvalid <= 1'b0;

            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;

                case (s_axi_araddr)
                    32'h00000000: begin
                        s_axi_rdata <= reg0;
                        s_axi_rresp <= 2'b00;
                    end

                    32'h00000004: begin
                        s_axi_rdata <= reg1;
                        s_axi_rresp <= 2'b00;
                    end

                    32'h00000008: begin
                        s_axi_rdata <= reg2;
                        s_axi_rresp <= 2'b00;
                    end

                    32'h0000000c: begin
                        s_axi_rdata <= reg3;
                        s_axi_rresp <= 2'b00;
                    end

                    default: begin
                        s_axi_rdata <= 32'b0;
                        s_axi_rresp <= 2'b10;
                    end
                endcase
            end
        end
    end

endmodule
